import { z } from "zod";

// Request schemas of the Kalorientracker API (/api/nutrition/*). Ids are generated by the client
// (offline-first); a repeated request with the same id is a no-op, not a duplicate.

export const NUTRIENT_FIELD_NAMES = ["kcal", "proteinG", "carbsG", "fatG", "fiberG", "sugarG", "saturatedFatG", "saltG"] as const;

// A nutrient value: null = unknown (never read as 0).
const nutrientValue = z.number().finite().nonnegative().max(100000).nullable();
const estimatedFieldsSchema = z.array(z.enum(NUTRIENT_FIELD_NAMES)).max(NUTRIENT_FIELD_NAMES.length).default([]);

export const nutrientsInputSchema = z.object({
  kcal: nutrientValue.default(null),
  proteinG: nutrientValue.default(null),
  carbsG: nutrientValue.default(null),
  fatG: nutrientValue.default(null),
  fiberG: nutrientValue.default(null),
  sugarG: nutrientValue.default(null),
  saturatedFatG: nutrientValue.default(null),
  saltG: nutrientValue.default(null),
});

// YYYY-MM-DD, a calendar day in the user's own timezone.
export const localDateSchema = z
  .string()
  .regex(/^\d{4}-\d{2}-\d{2}$/)
  .refine((s) => !Number.isNaN(Date.parse(`${s}T00:00:00Z`)) && new Date(`${s}T00:00:00Z`).toISOString().startsWith(s), "Ungültiges Datum");

const optionalText = (max: number) =>
  z
    .string()
    .trim()
    .max(max)
    .transform((v) => (v === "" ? null : v))
    .nullable()
    .optional();

const unitLabelSchema = z.string().trim().min(1).max(40);
const quantitySchema = z.number().finite().nonnegative().max(100000);

export const foodUnitInputSchema = z.object({
  id: z.string().uuid(),
  label: unitLabelSchema,
  baseAmount: z.number().finite().positive().max(100000),
});

// The user's own food (layer 1). Last write wins between devices, by clientUpdatedAt.
export const upsertFoodSchema = nutrientsInputSchema.extend({
  name: z.string().trim().min(1).max(200),
  brand: optionalText(120),
  barcode: z.string().trim().regex(/^\d{6,14}$/).nullable().optional(),
  basis: z.enum(["PER_100G", "PER_100ML"]).default("PER_100G"),
  densityGPerMl: z.number().finite().positive().max(5).nullable().optional(),
  estimatedFields: estimatedFieldsSchema,
  units: z.array(foodUnitInputSchema).max(20).optional(),
  clientUpdatedAt: z.string().datetime(),
});
export type UpsertFoodInput = z.infer<typeof upsertFoodSchema>;

// A household measure, also for a shared (BLS/OFF) food: "1 Stück Apfel = 150 g".
export const upsertFoodUnitSchema = z.object({
  foodId: z.string().uuid(),
  label: unitLabelSchema,
  baseAmount: z.number().finite().positive().max(100000),
  clientUpdatedAt: z.string().datetime(),
});
export type UpsertFoodUnitInput = z.infer<typeof upsertFoodUnitSchema>;

export const foodSearchQuerySchema = z.object({
  q: z.string().trim().min(2).max(100),
  limit: z.coerce.number().int().min(1).max(50).default(20),
});

export const recipeIngredientInputSchema = z.object({
  foodId: z.string().uuid(),
  quantity: quantitySchema,
  unitLabel: unitLabelSchema,
});

export const calculateRecipeSchema = z.object({
  servings: z.number().finite().positive().max(1000).nullable().optional(),
  // The weighed cooked dish; without it, per 100 g refers to the sum of the raw weights.
  finalWeightG: z.number().finite().nonnegative().max(100000).nullable().optional(),
  ingredients: z.array(recipeIngredientInputSchema).max(100),
});

export const upsertRecipeSchema = calculateRecipeSchema.extend({
  name: z.string().trim().min(1).max(200),
  note: optionalText(2000),
  clientUpdatedAt: z.string().datetime(),
});
export type UpsertRecipeInput = z.infer<typeof upsertRecipeSchema>;

// A snapshot taken by the client (e.g. offline, from its own copy of the food). Kept as sent:
// it is the user's own record of what they ate.
export const entrySnapshotSchema = nutrientsInputSchema.extend({
  grams: z.number().finite().nonnegative().max(100000).nullable().default(null),
  estimatedFields: estimatedFieldsSchema,
});

// What was eaten: a food, a recipe (unit "g" or "Portion"), or a free entry with its own values.
export const mealEntryInputSchema = z
  .object({
    id: z.string().uuid(),
    foodId: z.string().uuid().nullable().optional(),
    recipeId: z.string().uuid().nullable().optional(),
    name: z.string().trim().min(1).max(200).optional(),
    brand: optionalText(120),
    quantity: quantitySchema,
    unitLabel: unitLabelSchema,
    snapshot: entrySnapshotSchema.optional(),
  })
  .refine((e) => !(e.foodId && e.recipeId), "Entweder foodId oder recipeId, nicht beides")
  .refine((e) => e.foodId || e.recipeId || (e.snapshot && e.name), "Ein freier Eintrag braucht Name und Nährwerte");
export type MealEntryInput = z.infer<typeof mealEntryInputSchema>;

export const MEAL_TYPES = ["BREAKFAST", "LUNCH", "DINNER", "SNACK"] as const;

export const createMealLogSchema = z.object({
  id: z.string().uuid(),
  date: localDateSchema,
  mealType: z.enum(MEAL_TYPES),
  eatenAt: z.string().datetime().nullable().optional(),
  note: optionalText(500),
  entries: z.array(mealEntryInputSchema).max(50).default([]),
});
export type CreateMealLogInput = z.infer<typeof createMealLogSchema>;

export const addMealEntriesSchema = z.object({
  entries: z.array(mealEntryInputSchema).min(1).max(50),
});

export const dateRangeQuerySchema = z.object({
  from: localDateSchema,
  to: localDateSchema,
});

export const setRatingSchema = z.object({
  id: z.string().uuid(),
  score: z.number().int().min(1).max(10),
  note: optionalText(280),
});
export type SetRatingInput = z.infer<typeof setRatingSchema>;

export const nutritionSettingsSchema = z.object({
  // Share of the calories left after protein that goes to fat; the rest is carbohydrates.
  fatPercentOfRemaining: z.number().int().min(10).max(90),
});

const ids = z.array(z.string().uuid()).max(500).default([]);

// Offline changes in one request. Applied one by one; the answer says what happened to each.
export const nutritionSyncPushSchema = z.object({
  foods: z.array(upsertFoodSchema.extend({ id: z.string().uuid() })).max(200).default([]),
  foodUnits: z.array(upsertFoodUnitSchema.extend({ id: z.string().uuid() })).max(500).default([]),
  recipes: z.array(upsertRecipeSchema.extend({ id: z.string().uuid() })).max(100).default([]),
  mealLogs: z.array(createMealLogSchema).max(200).default([]),
  mealEntries: z.array(z.object({ mealLogId: z.string().uuid(), entry: mealEntryInputSchema })).max(500).default([]),
  ratings: z.array(setRatingSchema.extend({ date: localDateSchema })).max(100).default([]),
  deletions: z
    .object({ foods: ids, foodUnits: ids, recipes: ids, mealLogs: ids, mealEntries: ids, ratings: ids })
    .default({ foods: [], foodUnits: [], recipes: [], mealLogs: [], mealEntries: [], ratings: [] }),
});
export type NutritionSyncPush = z.infer<typeof nutritionSyncPushSchema>;

export const nutritionSyncPullQuerySchema = z.object({
  updatedSince: z.string().datetime().optional(),
});

export const NUTRITION_EXPORT_FORMATS = ["pdf", "csv", "md", "json"] as const;

export const nutritionExportQuerySchema = z
  .object({
    days: z.coerce.number().int().refine((d) => [7, 14, 31, 90].includes(d), "7, 14, 31 oder 90 Tage").optional(),
    from: localDateSchema.optional(),
    to: localDateSchema.optional(),
    format: z.enum(NUTRITION_EXPORT_FORMATS).default("json"),
  })
  .refine((q) => (q.days !== undefined) !== (q.from !== undefined && q.to !== undefined), "Entweder days oder from und to")
  .refine((q) => !(q.from && q.to) || q.from <= q.to, "from muss vor to liegen");
export type NutritionExportQuery = z.infer<typeof nutritionExportQuerySchema>;
